// Conditional routing: Reviewer -> {Implementer, Converger}

const fs = require('fs');
const path = require('path');

const INPUT = path.resolve('.graft/session/node_outputs/reviewer.json');
const ROUTE = path.resolve('.graft/session/routing/reviewer_route.json');

