if (data["approved"] === false) {
  target = "Implementer";
} else {
  target = "Converger";
}

fs.mkdirSync(path.dirname(ROUTE), { recursive: true });
fs.writeFileSync(ROUTE, JSON.stringify({ target, from: "Reviewer" }, null, 2));
